#!/usr/bin/env python3
# =====================================================================
#  apply_entry_fast_confirm.py  —  fence ENTRY_FAST_CONFIRM_20261109
#
#  ⚠ LIVE ORDER TIMING for the four core strategies (approved 2026-11-09).
#  Entry legs go one after another (wing/hedge first, then the short), and
#  each leg waited for a poll before the next was sent. 2026-11-09
#  Timberwolf: hedge filled 13:56:03, the 2-s poll saw it ~13:56:05, the
#  short filled 13:56:07 at the minute's low (153.20 vs model 159.30).
#
#   TMA_V2  tma2_trade_manager.py   fill poll 2 s → 0.3 s; the margin
#           pre-check runs at SIGNAL time (during the waiting minute), not
#           at the boundary — same check, same fail-open; a failed pre-check
#           is simply re-run at the boundary as before
#   IC_V2   ic_group_manager.py     fill poll 2 s → 0.3 s
#   TSG_V1  tsg_manager.py          fill poll 1 s → 0.3 s (re-peg windows
#           unchanged); ENTRY_WAIT heartbeat kept to ~1 line a second
#   VET_V1  vet_manager.py          order driver poll 1 s → 0.3 s (entries,
#           flips and exits; chase / re-peg timings unchanged)
#   tests   backend/app/engine/test_entry_fast_confirm.py (new, 15 checks)
#
#  NOT in this script (needs your decision, see chat): buying Timberwolf's
#  hedge during the waiting minute (orphan-on-restart risk to handle first).
#  No order types, prices, sizes or sequences change — only how fast a fill
#  is noticed. ~3.3 status calls/s per strategy entering, within Kite limits.
#
#  Run ONLY this script, outside market hours:
#     cd ~/dev/scalp-app && python3 apply_entry_fast_confirm.py
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
#  Then: ./desktop/build-scalp.sh both, restart the app.
#  Icarus' pytest suites: cd backend/app/engine/ic && PYTHONPATH=../../..:. python3 -m pytest -q <file>
# =====================================================================
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "ENTRY_FAST_CONFIRM_20261109"
ITEMS = json.loads(r'''[{"path": "backend/app/engine/tma2/tma2_trade_manager.py", "orig": "dc4e8d27c812825cec770856af11b65f724123a9d6581c30a683dc9e96a485fa", "new": "6e8167b53623d166a6678a2ff5174a730dcc7bade5a7c530e22ae664501dbe11", "blob": ""}, {"path": "backend/app/engine/ic/ic_group_manager.py", "orig": "f23d762e0d37bf549755654851fd243e977ee892a7559d6d237c17b10b1282ab", "new": "cbb245824df3983bbe8be81dbead0beaf0294ab80682c9dd3cc3719ef934bc6a", "blob": ""}, {"path": "backend/app/engine/tsg/tsg_manager.py", "orig": "be4621cc0028fdb5d1534698e48914de31dd1dbc0df7cb1b5bd67c1dac9c8b17", "new": "048de9fb848facabb5837887786d5c159f616b2fb446352878e8e7211af857a0", "blob": ""}, {"path": "backend/app/engine/vet/vet_manager.py", "orig": "9234d636a51c4728dde910db9458a56e13c2700b8f90fc2a5a5c57dc49fa2dbc", "new": "11779e0e9ce0eda25dcf606257b1f3a319c110f794c83338697fbd1a3467f091", "blob": ""}, {"path": "backend/app/engine/test_entry_fast_confirm.py", "orig": null, "new": "822b64890a9a532d17c4025464fa6435f562456e56638a573f9fe735a9d2236f", "blob": ""}]''')
BUILD_COPIES = {"backend/": "desktop/src-tauri/backend/", "frontend/": "desktop/src-tauri/frontend/"}
TESTS = ["app/engine/test_entry_fast_confirm.py", "app/engine/tma2/test_tma2_e2e.py",
         "app/engine/tma2/test_tma2_entry_paths.py", "app/engine/tma2/test_tma2_exit_paths.py",
         "app/engine/tma2/test_tma_paper_fallback.py", "app/engine/tsg/test_tsg_e2e.py",
         "app/engine/tsg/test_tsg_exit_confirm.py", "app/engine/vet/test_vet_e2e.py",
         "app/engine/vet/test_vet_live_confirm.py", "app/engine/vet/test_vet_manager.py",
         "app/engine/ic/test_ic2_shadow_carry.py"]


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


args = sys.argv[1:]
repo = os.path.expanduser(args[args.index("--repo") + 1]) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")


def targets():
    """(item, absolute path, is_build_copy)"""
    out = []
    for it in ITEMS:
        out.append((it, os.path.join(repo, it["path"]), False))
        for a, b in BUILD_COPIES.items():
            if it["path"].startswith(a):
                p = os.path.join(repo, b + it["path"][len(a):])
                if os.path.isdir(os.path.dirname(p)):
                    out.append((it, p, True))
    return out


# ── rollback mode ────────────────────────────────────────────────────
if "--rollback" in args:
    n = 0
    for it, p, _ in targets():
        bak = p + ".bak-" + FENCE
        if os.path.exists(bak):
            shutil.copy2(bak, p)
            os.remove(bak)
            n += 1
        elif it["orig"] is None and os.path.exists(p):
            with open(p, "rb") as f:
                if sha(f.read()) == it["new"]:
                    os.remove(p)
                    n += 1
    say(f"rolled back {n} file(s)")
    sys.exit(0)

# ── 1. state of every target ─────────────────────────────────────────
plan, done, skipped = [], 0, []
for it, p, build in targets():
    cur = open(p, "rb").read() if os.path.exists(p) else None
    cs = sha(cur) if cur is not None else None
    rel = os.path.relpath(p, repo)
    if cs == it["new"]:
        done += 1
        continue
    if cs == it["orig"]:
        plan.append((it, p, cur, build))
        continue
    if build:
        skipped.append(rel)              # a stale build copy — the build re-syncs it
        continue
    if cur is None:
        die(f"{rel} is missing")
    die(f"{rel} differs from GitHub main and from the patched version — local edits? "
        f"(commit/stash them or pull main, then re-run)")
if not plan:
    say(f"✓ already applied ({done} file(s) carry {FENCE}) — nothing to do")
    sys.exit(0)

# ── 2. git status: an uncommitted change on a target is a stop sign ──
if "--allow-dirty" not in args:
    try:
        rels = [os.path.relpath(p, repo) for _, p, _, b in plan if not b]
        st = subprocess.run(["git", "status", "--porcelain", "--"] + rels, cwd=repo,
                            capture_output=True, text=True, timeout=30).stdout
        dirty = [l for l in st.splitlines() if l[:2].strip() and not l.startswith("??")]
        if dirty:
            die("uncommitted changes on target files:\n  " + "\n  ".join(dirty) + "\n  (re-run with --allow-dirty to override)")
    except FileNotFoundError:
        say("  (git not found — skipping the status check)")

# ── 3. decode + compile every payload before writing anything ───────
tmp = tempfile.mkdtemp(prefix="vet_near_obs_")
blobs = {}
for it in ITEMS:
    b = zlib.decompress(base64.b64decode(it["blob"]))
    if sha(b) != it["new"]:
        die(f"payload for {it['path']} is corrupt")
    blobs[it["path"]] = b
    if it["path"].endswith(".py"):
        f = os.path.join(tmp, os.path.basename(it["path"]))
        open(f, "wb").write(b)
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {it['path']} does not compile: {e}")
say(f"payloads verified and compiled ({len(ITEMS)} files)")

# ── 4. write, all or nothing ─────────────────────────────────────────
written = []


def restore():
    for p, old in reversed(written):
        try:
            if old is None:
                os.remove(p)
            else:
                open(p, "wb").write(old)
            bak = p + ".bak-" + FENCE
            if os.path.exists(bak):
                os.remove(bak)
        except Exception as e:
            say(f"  !! could not restore {p}: {e}")


try:
    for it, p, cur, build in plan:
        if cur is not None:
            open(p + ".bak-" + FENCE, "wb").write(cur)
        t = p + ".tmp-" + FENCE
        open(t, "wb").write(blobs[it["path"]])
        os.replace(t, p)
        written.append((p, cur))
        say(f"  wrote {os.path.relpath(p, repo)}{'  (build copy)' if build else ''}")
except Exception as e:
    restore()
    die(f"write failed ({e!r}) — everything restored")
for s_ in skipped:
    say(f"  skipped stale build copy {s_} (the next build re-syncs it)")

# ── 5. tests ─────────────────────────────────────────────────────────
backend = os.path.join(repo, "backend")
py = next((c for c in (os.path.join(backend, "venv", "bin", "python"), os.path.join(backend, ".venv", "bin", "python"),
                       os.path.join(repo, "venv", "bin", "python"), os.path.join(repo, ".venv", "bin", "python"))
           if os.path.exists(c)), sys.executable)
if "--skip-tests" in args:
    say("tests skipped (--skip-tests)")
else:
    say(f"running tests with {py}")
    env = dict(os.environ, PYTHONPATH=backend)
    failed, envmiss = [], []
    for t in TESTS:
        if not os.path.exists(os.path.join(backend, t)):
            continue
        try:
            r = subprocess.run([py, t], cwd=backend, env=env, capture_output=True, text=True, timeout=600)
            outp = (r.stdout or "") + (r.stderr or "")
        except subprocess.TimeoutExpired:
            r, outp = None, "timeout"
        last = (outp.strip().splitlines() or [""])[-1]
        if r is not None and r.returncode == 0:
            say(f"  ✓ {t}  {last}")
        elif "ModuleNotFoundError" in outp and "No module named 'app" not in outp:
            envmiss.append(t)
            say(f"  ? {t}  could not run here: {last}")
        else:
            failed.append(t)
            say(f"  ✗ {t}\n" + "\n".join("      " + l for l in outp.strip().splitlines()[-25:]))
    if failed:
        restore()
        die("tests failed: " + ", ".join(failed) + " — every file restored")
    if envmiss:
        say("  note: some suites need the backend's Python packages; re-run them with that Python")

shutil.rmtree(tmp, ignore_errors=True)
say(f"\n✓ {FENCE} applied ({len(written)} file(s)). Next: ./desktop/build-scalp.sh both, then restart the app.")
say("  Undo: python3 apply_entry_fast_confirm.py --rollback")
